def selected_source(q,f):
 p=str(f.relative_to(S/q['repo']/'files'));lo=p.lower();name=f.name.lower()
 if f.suffix.lower()in['.bin','.pdf','.html']:return True
 if name.startswith('readme')and p.count('/')<2:return True
 if f.suffix.lower()not in['.h','.c','.cpp','.ino','.csv','.txt','.yml','.lock']:return False
 if 'registry/esp32_c6_touch_amoled_2_06/'in lo:return True
 if q['repo'].endswith('AMOLED-2.06'):return 'examples/esp-idf/02_lvgl_demo_v9/main/'in lo or name in ['port_axp2101.cpp','port_axp2101.h']
 if q['repo'].endswith('AMOLED-1.43'):return '/11_factoryprogram/'in lo and any(x in lo for x in ['/src/port_bsp/','user_config.h','11_factoryprogram.ino','/components/i2c_equipment/'])
 if q['repo'].endswith('LCD-1.69'):return '/01_factory/'in lo and('/components/esp_bsp/'in lo or'/main/'in lo)
 return 'examples/factory/'in lo and any(x in lo for x in ['/components/esp_bsp/','/components/esp_lcd_touch_axs5106/','/components/esp_lcd_jd9853/','/main/'])

